#!/usr/bin/env python3
"""Compare reference.diff and generated.patch per-file added/removed lines.

Independent validation helper: it only reads patch text, no repo mutation.
"""
import re
import sys
from pathlib import Path


def parse_patch(path):
    files = {}
    cur = None
    for raw in Path(path).read_text(encoding="utf-8", errors="replace").splitlines():
        if raw.startswith("diff --git "):
            m = re.search(r" b/(\S+)$", raw)
            cur = m.group(1) if m else None
            files.setdefault(cur, {"plus": [], "minus": []})
        elif raw.startswith("+++ ") or raw.startswith("--- "):
            continue
        elif cur is not None:
            if raw.startswith("+"):
                files[cur]["plus"].append(raw[1:])
            elif raw.startswith("-"):
                files[cur]["minus"].append(raw[1:])
    return files


def main():
    ref = parse_patch(sys.argv[1])
    gen = parse_patch(sys.argv[2])
    ok = True
    for path in sorted(set(ref) | set(gen)):
        r = ref.get(path, {"plus": [], "minus": []})
        g = gen.get(path, {"plus": [], "minus": []})
        same_plus = r["plus"] == g["plus"]
        same_minus = r["minus"] == g["minus"]
        print(f"{path}")
        print(f"  plus lines: ref={len(r['plus'])} gen={len(g['plus'])} identical={same_plus}")
        print(f"  minus lines: ref={len(r['minus'])} gen={len(g['minus'])} identical={same_minus}")
        if not (same_plus and same_minus):
            ok = False
            for i, (a, b) in enumerate(zip(r["plus"], g["plus"])):
                if a != b:
                    print(f"    first plus diff at index {i}: ref={a!r} gen={b!r}")
                    break
            for i, (a, b) in enumerate(zip(r["minus"], g["minus"])):
                if a != b:
                    print(f"    first minus diff at index {i}: ref={a!r} gen={b!r}")
                    break
    print("RESULT:", "IDENTICAL_CONTENT" if ok else "DIFFERS")
    return 0 if ok else 1


if __name__ == "__main__":
    raise SystemExit(main())

